package nir.com.neonvegasslots;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.util.*;import android.graphics.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) public class SpecialFeatureJournalTest {
 @Before public void clear(){RuntimeEnvironment.getApplication().getSharedPreferences("special_feature_disabled_v1",0).edit().clear().commit();}
 @Test public void actualJournalRestoresGridAndSettlesOnce(){android.content.Context c=RuntimeEnvironment.getApplication();SpecialFeature f=new SpecialFeature(c);f.initialize(500);SpecialFeature.State s=f.begin(10,new Random(8));SpecialFeature recovered=new SpecialFeature(c);assertEquals(java.util.Arrays.deepToString(s.grid),java.util.Arrays.deepToString(recovered.snapshot().grid));}
 @Test public void fiveFreeSpinsKeepTriggerStakeAndNeverDebit(){android.content.Context c=RuntimeEnvironment.getApplication();SpecialFeature f=new SpecialFeature(c);SpecialFeature.State trigger=f.begin(10,new Random(){public double nextDouble(){return 0;}});assertEquals(3,trigger.grid.length);SpecialFeature.State award=f.settle(trigger.sequence);assertEquals(5,award.remaining);long balance=award.balance;for(int i=0;i<5;i++){SpecialFeature.State spin=f.begin(200,new Random(9+i));assertTrue(spin.free);assertEquals(10,spin.stake);assertEquals(balance,spin.balance);assertEquals(0,SpecialFeature.scatterReels(spin.grid,5));award=f.settle(spin.sequence);balance=award.balance;}assertEquals(0,award.remaining);}
 @Test public void duplicateSettlementAndRestartDoNotCreditAgain(){android.content.Context c=RuntimeEnvironment.getApplication();SpecialFeature f=new SpecialFeature(c);SpecialFeature.State s=f.begin(10,new Random(8));long expected=490+s.award;assertEquals(expected,f.settle(s.sequence).balance);assertEquals(expected,new SpecialFeature(c).settle(s.sequence).balance);}
 @GraphicsMode(GraphicsMode.Mode.NATIVE) @Test public void symbolPreview()throws Exception{Bitmap b=Bitmap.createBitmap(480,280,Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(b);cv.drawColor(0xFF09091A);SpecialFeature.symbol(cv,6,120,130,200,1200,true,false);SpecialFeature.symbol(cv,7,360,130,200,1200,true,false);try(java.io.FileOutputStream o=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-special-candidate.png")){b.compress(Bitmap.CompressFormat.PNG,100,o);}assertFalse(SpecialFeature.ENABLED);}
}
